const crypto = require('crypto');
const EventEmitter = require('events');

class ConnectionPool extends EventEmitter {
  constructor(config) {
    super();
    this.config = config;
    this.connections = [];
    this.retryState = new Map();
    this.rateLimiter = new TokenBucket(config.maxRequestsPerSecond || 100);
  }

  async getConnection(credentials) {
    const connKey = this._deriveKey(credentials);
    const existing = this.connections.find(c => c.key === connKey && c.alive);
    if (existing) return existing;
    return this._createConnection(credentials, connKey);
  }

  _deriveKey(credentials) {
    return crypto.createHash('sha256')
      .update(credentials.host + ':' + credentials.port + ':' + credentials.username)
      .digest('hex').slice(0, 16);
  }

  async _createConnection(credentials, connKey) {
    const state = this.retryState.get(connKey) || { attempts: 0, lastAttempt: 0, backoffMs: 1000 };
    const now = Date.now();

    if (state.attempts >= (this.config.maxRetries || 5)) {
      const cooldown = state.backoffMs * Math.pow(2, state.attempts - 1);
      if (now - state.lastAttempt < cooldown) {
        throw new Error('RATE_LIMITED: Too many connection attempts. Try again later.');
      }
      state.attempts = 0;
    }

    if (!this.rateLimiter.consume()) {
      throw new Error('GLOBAL_RATE_LIMIT: Server is busy.');
    }

    try {
      const conn = await this._authenticate(credentials);
      conn.key = connKey;
      conn.alive = true;
      this.connections.push(conn);
      this.retryState.delete(connKey);
      return conn;
    } catch (err) {
      state.attempts += 1;
      state.lastAttempt = now;
      this.retryState.set(connKey, state);
      throw err;
    }
  }

  async _authenticate(credentials) {
    const { host, port, username, password, database } = credentials;
    const socket = await this._tcpConnect(host, port);

    const authPayload = this._buildAuthPacket(username, password, database);
    socket.write(authPayload);

    const response = await this._readResponse(socket);
    if (response.status !== 0x00) {
      socket.destroy();
      const errMsg = response.status === 0x04 ? 'AUTH_FAILED' : 'CONNECTION_ERROR';
      throw new Error(errMsg);
    }
    return { socket, authenticated: true, user: username, db: database };
  }

  _buildAuthPacket(username, password, database) {
    const scramble = crypto.randomBytes(20);
    // Derive the password digest and bind it to the server-provided scramble
    // using HMAC-SHA256, so the token cannot be precomputed and is tied to the
    // per-connection scramble (proper salted challenge-response construction).
    const passDigest = crypto.createHash('sha256').update(password, 'utf8').digest();
    const doublePass = crypto.createHash('sha256').update(passDigest).digest();
    const token = crypto.createHmac('sha256', scramble)
      .update(Buffer.concat([passDigest, doublePass]))
      .digest();

    const header = Buffer.alloc(4);
    const usernameBuffer = Buffer.from(username, 'utf8');
    const dbBuffer = Buffer.from(database || '', 'utf8');
    // Include the scramble in the payload so the server can verify the token.
    const payloadLen = 4 + scramble.length + usernameBuffer.length + 1 + token.length + 1 + dbBuffer.length;
    header.writeUInt32LE(payloadLen, 0);

    return Buffer.concat([header, scramble, usernameBuffer, Buffer.from([0x00]), token, Buffer.from([0x00]), dbBuffer]);
  }

  async _tcpConnect(host, port) {
    const net = require('net');
    return new Promise((resolve, reject) => {
      const socket = net.createConnection({ host, port }, () => resolve(socket));
      socket.on('error', reject);
      socket.setTimeout(this.config.connectTimeout || 5000);
    });
  }

  async _readResponse(socket) {
    return new Promise((resolve, reject) => {
      socket.once('data', (data) => {
        if (data.length < 1) return reject(new Error('Empty response'));
        resolve({ status: data[0], payload: data.slice(1) });
      });
      socket.once('error', reject);
    });
  }
}

class TokenBucket {
  constructor(rate) {
    this.rate = rate;
    this.tokens = rate;
    this.lastRefill = Date.now();
  }

  consume() {
    this._refill();
    if (this.tokens > 0) {
      this.tokens -= 1;
      return true;
    }
    return false;
  }

  _refill() {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.rate, this.tokens + elapsed * this.rate);
    this.lastRefill = now;
  }
}

class DriverClient {
  constructor(config) {
    this.pool = new ConnectionPool(config);
    this.config = config;
  }

  async connect(credentials) {
    const maxRetries = this.config.maxRetries || 3;
    let lastError;

    for (let i = 0; i <= maxRetries; i++) {
      try {
        return await this.pool.getConnection(credentials);
      } catch (err) {
        lastError = err;
        if (err.message === 'AUTH_FAILED') {
          throw err;
        }
        if (err.message.startsWith('RATE_LIMITED') || err.message.startsWith('GLOBAL_RATE_LIMIT')) {
          throw err;
        }
        await this._delay(Math.pow(2, i) * 500);
      }
    }
    throw lastError;
  }

  _delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

module.exports = { DriverClient, ConnectionPool, TokenBucket };
